import{_ as o,C as d,o as t,c as n,a2 as s,b as r,w as i,a as h,E as c,a3 as l}from"./chunks/framework.dK2ol1xu.js";const f=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"CONTRIBUTING.md","filePath":"CONTRIBUTING.md"}'),p={name:"CONTRIBUTING.md"};function g(k,e,u,m,b,y){const a=d("Mermaid");return t(),n("div",null,[e[1]||(e[1]=s('<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Coach Poulpy is built mostly by talking to Claude, using <a href="https://github.com/mattpocock/skills" target="_blank" rel="noreferrer">Matt Pocock&#39;s engineering skills</a>. This page says which skill to reach for, in what order, and what each one leaves behind in the repo or on GitHub.</p><p>Everything below works the same in a Claude Code terminal (type <code>/triage</code>, <code>/to-spec</code>...) and in a Claude project thread (write &quot;triage #12&quot; or &quot;run to-spec on this&quot;). Skills marked <em>auto</em> are picked up by Claude without being named.</p><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2>',4)),(t(),r(l,null,{default:i(()=>[c(a,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20idea(%5BAn%20idea%5D)%20--%3E%20grill%5B%22%2Fgrill-with-docs%22%5D%0A%20%20%20%20huge(%5BA%20huge%2C%20foggy%20effort%5D)%20--%3E%20wayfinder%5B%22%2Fwayfinder%22%5D%0A%20%20%20%20raw(%5BA%20raw%20issue%20or%20bug%20report%5D)%20--%3E%20triage%5B%22%2Ftriage%22%5D%0A%20%20%20%20broken(%5BSomething%20is%20broken%5D)%20--%3E%20diagnose%5B%22%2Fdiagnosing-bugs%22%5D%0A%0A%20%20%20%20grill%20%3C-.%20%22need%20to%20see%20it%20run%3F%22%20.-%3E%20prototype%5B%22%2Fprototype%22%5D%0A%20%20%20%20grill%20--%3E%20multi%7B%22More%20than%3Cbr%2F%3Eone%20session%3F%22%7D%0A%20%20%20%20wayfinder%20--%3E%20spec%0A%20%20%20%20multi%20--%20yes%20--%3E%20spec%5B%22%2Fto-spec%22%5D%20--%3E%20tickets%5B%22%2Fto-tickets%22%5D%20--%3E%20implement%0A%20%20%20%20multi%20--%20no%20--%3E%20implement%5B%22%2Fimplement%3Cbr%2F%3Ewith%20%2Ftdd%22%5D%0A%20%20%20%20triage%20--%20ready-for-agent%20--%3E%20implement%0A%20%20%20%20triage%20--%20ready-for-human%20--%3E%20human(%5BYou%20do%20it%5D)%0A%0A%20%20%20%20implement%20--%3E%20review%5B%22%2Fcode-review%22%5D%0A%20%20%20%20diagnose%20--%3E%20review%0A%20%20%20%20review%20--%3E%20pr%5B%22PR%3A%20Closes%20%23n%22%5D%20--%3E%20ci%7B%22CI%20green%3F%3Cbr%2F%3EPhone%20checked%3F%22%7D%0A%20%20%20%20ci%20--%20yes%20--%3E%20merge(%5BMerge%20closes%20the%20issue%5D)%0A%20%20%20%20ci%20--%20no%20--%3E%20implement%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s(`<p>Rounded boxes are where work starts; each step leaves something behind, listed in the table below.</p><h2 id="which-skill-when" tabindex="-1">Which skill when <a class="header-anchor" href="#which-skill-when" aria-label="Permalink to &quot;Which skill when&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You have</th><th>Use</th><th>It leaves behind</th></tr></thead><tbody><tr><td>A loose idea</td><td><code>/grill-with-docs</code></td><td>Sharper terms in <code>CONTEXT.md</code>, an ADR when a hard-to-reverse choice is made</td></tr><tr><td>An idea you can only judge by trying it</td><td><code>/prototype</code></td><td>Throwaway code, never merged</td></tr><tr><td>A grilled idea worth more than one session</td><td><code>/to-spec</code>, then <code>/to-tickets</code></td><td>A spec issue, then <code>ready-for-agent</code> sub-issues with blocked-by links</td></tr><tr><td>A small, grilled change</td><td><code>/implement</code></td><td>A branch with tests, reviewed by <code>/code-review</code></td></tr><tr><td>Issues you didn&#39;t write (bugs, requests)</td><td><code>/triage</code></td><td>Labels, triage notes or an agent brief on the issue</td></tr><tr><td>A bug that resists a first look</td><td><code>/diagnosing-bugs</code></td><td>A fix with a regression test</td></tr><tr><td>A huge effort with no clear path</td><td><code>/wayfinder</code></td><td>A <code>wayfinder:map</code> issue whose tickets are decisions, handed to <code>/to-spec</code> when clear</td></tr><tr><td>A module that feels wrong</td><td><code>/codebase-design</code> <em>auto</em></td><td>A smaller interface at a cleaner seam</td></tr><tr><td>A question to research</td><td><code>/research</code> <em>auto</em></td><td>A cited Markdown note in the repo</td></tr></tbody></table><p><code>/tdd</code>, <code>/grilling</code>, <code>/domain-modeling</code>, <code>/code-review</code> and <code>/writing-for-agents</code> are <em>auto</em>: the skills above call them, and Claude reaches for them when a task fits.</p><h2 id="habits-that-keep-it-working" tabindex="-1">Habits that keep it working <a class="header-anchor" href="#habits-that-keep-it-working" aria-label="Permalink to &quot;Habits that keep it working&quot;">​</a></h2><ul><li><strong>One goal per thread or session.</strong> Grill, spec and tickets in one unbroken conversation; then each ticket starts fresh, because the ticket carries everything it needs.</li><li><strong>Don&#39;t triage what <code>/to-tickets</code> made.</strong> Those issues are born <code>ready-for-agent</code>.</li><li><strong>Read the area&#39;s rules.</strong> <a href="./docs/agents/areas"><code>docs/agents/areas.md</code></a> has what the Architect, Designer, Poulpy and Translator used to carry in their heads, per area. A spec or ticket reads the sections it touches; one review per PR covers the rest.</li><li><strong>Words come from <code>CONTEXT.md</code>.</strong> If an issue or a test needs a word the glossary lacks, add it there first.</li><li><strong>A decision that would surprise the next reader gets an ADR</strong> in <code>docs/adr/</code>, in the same PR that makes it.</li><li><strong>Every PR says <code>Closes #n</code></strong>, so merging closes the issue.</li><li><strong>Branch names say what the work is</strong>: <code>&lt;type&gt;/&lt;issue-number&gt;-&lt;short-description&gt;</code>, in English, like <code>feat/21-training-plans</code> or <code>fix/34-rest-timer-sound</code>. Leave out the number when there is no issue (<code>docs/brand-decisions</code>). Types are <code>feat</code>, <code>fix</code>, <code>docs</code>, <code>chore</code> and <code>design</code>. No random suffixes, session ids or tool prefixes such as <code>claude/</code>.</li><li><strong>The docs site is the source of truth, so a PR is reviewed there.</strong> On every PR, the Docs site workflow publishes a preview and posts a &quot;Review in the docs&quot; comment, both without an agent. It links each spec, mockup, decision or guideline the PR adds or changes, down to the sections and glossary entries it touches, and the agreed mockups drawn for the issue the PR closes. Agents don&#39;t write a review comment of their own; anything the reviewer must know, such as a known difference from a mockup, goes in the PR description.</li><li><strong>Every guideline is on the docs site.</strong> A new rule, glossary or ADR is published in the same PR that adds it: add its file to <code>site/published.mjs</code> and a sidebar entry in <code>site/.vitepress/config.mts</code>. CI fails on a Markdown file the site doesn&#39;t publish or a page no link reaches.</li><li><strong>CI is not a phone.</strong> Anything about Bluetooth, sound, haptics, background running or installs carries the <code>device-test</code> label and is checked on a real phone before merge.</li></ul><h2 id="labels" tabindex="-1">Labels <a class="header-anchor" href="#labels" aria-label="Permalink to &quot;Labels&quot;">​</a></h2><p>Every issue has one type, one state and at least one area, and sits in its phase&#39;s milestone. The labels are defined in <a href="https://github.com/tkint/coach-poulpy/blob/main/.github/labels.yml" target="_blank" rel="noreferrer"><code>.github/labels.yml</code></a> and synced to GitHub when that file changes on <code>main</code>.</p><table tabindex="0"><thead><tr><th>Group</th><th>Labels</th></tr></thead><tbody><tr><td>Type</td><td><code>bug</code>, <code>enhancement</code>, <code>documentation</code></td></tr><tr><td>State</td><td><code>needs-triage</code> → <code>needs-info</code>, <code>ready-for-agent</code>, <code>ready-for-human</code> or <code>wontfix</code></td></tr><tr><td>Area</td><td><code>area:shared</code>, <code>area:android</code>, <code>area:ios</code>, <code>area:devices</code>, <code>area:catalog</code>, <code>area:server</code>, <code>area:web</code>, <code>area:design</code></td></tr><tr><td>Check</td><td><code>device-test</code></td></tr><tr><td>Wayfinder</td><td><code>wayfinder:map</code>, <code>wayfinder:research</code>, <code>wayfinder:prototype</code>, <code>wayfinder:grilling</code>, <code>wayfinder:task</code></td></tr></tbody></table><p>How agents read the tracker and the domain docs is in <a href="https://github.com/tkint/coach-poulpy/tree/main/docs/agents/" target="_blank" rel="noreferrer"><code>docs/agents/</code></a>.</p><h2 id="running-and-checking-the-code" tabindex="-1">Running and checking the code <a class="header-anchor" href="#running-and-checking-the-code" aria-label="Permalink to &quot;Running and checking the code&quot;">​</a></h2><p>See the <a href="https://github.com/tkint/coach-poulpy/blob/main/README.md" target="_blank" rel="noreferrer">README</a> for building each app. Before opening a PR, at least run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jvmTest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsTest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :server:test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :tools:i18n:test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-tokens.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design/build-poulpy.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p>When a change touches Markdown, CI also lints it, checks its links and checks the site publishes it. To run the same checks first (lychee is a separate install, see <a href="https://github.com/lycheeverse/lychee#installation" target="_blank" rel="noreferrer">its README</a>):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> markdownlint-cli2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lychee</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lychee.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;./**/*.md&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-published.mjs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div>`,15))])}const F=o(p,[["render",g]]);export{f as __pageData,F as default};
